// Live metadata is fetched through Folio's backend; credentials never enter this file.
const metadataPanel=document.createElement('section');
metadataPanel.className='heading';
metadataPanel.innerHTML='<div><h2>Search live metadata</h2><form id="live-form"><label>Title <input id="live-query" required maxlength="200"></label> <label>Media <select id="live-kind"><option value="movie">Movies</option><option value="tv">TV</option><option value="manga">Manga / manhwa</option><option value="visual_novel">Visual novels</option><option value="game">Games</option><option value="album">Music albums</option><option value="track">Music recordings</option><option value="anime">Anime</option></select></label> <button class="primary">Search providers</button></form><p id="live-status" role="status">Live search requires the metadata service. Your saved library is unchanged.</p><div id="live-results"></div></div>';
document.querySelector('#library-page').prepend(metadataPanel);
const mediaTypes={movie:'Movie',tv:'TV show',manga:'Manga',visual_novel:'Visual novel',game:'Game',album:'Music',track:'Music',anime:'Anime'};
if(!types.includes('Manga')){types.push('Manga');labels.push('Manga');}
owned=function(x){return items.find(y=>FolioIdentity.same(y,x));};
let liveSequence=0;
async function metadataGet(path){const r=await fetch('/api/metadata/'+path);const body=await r.json();if(!r.ok)throw Error(typeof body.detail==='string'?body.detail:'This provider is unavailable or needs configuration.');return body;}
function fromMetadata(m){return {id:m.id,title:m.title,type:mediaTypes[m.kind],year:m.release_date?.slice(0,4)||'',creator:(m.creators||[]).join(', '),genre:m.genres.join(', '),description:m.description||'',symbol:'✦',color:colors[0],sources:(m.ratings||[]).concat(...(m.enrichments||[]).map(e=>e.ratings||[])).map(r=>[r.label,r.value]),metadata:m,added:Date.now()};}
document.querySelector('#live-form').onsubmit=async e=>{e.preventDefault();const seq=++liveSequence;const status=document.querySelector('#live-status'),results=document.querySelector('#live-results');status.textContent='Searching providers…';results.replaceChildren();try{const data=await metadataGet('search?'+new URLSearchParams({q:document.querySelector('#live-query').value,kind:document.querySelector('#live-kind').value}));if(seq!==liveSequence)return;status.textContent=data.partial?'Some providers are unavailable. Available results are shown.':data.results.length+' results';for(const m of data.results){const x=fromMetadata(m),row=document.createElement('p'),label=document.createElement('span'),button=document.createElement('button');label.textContent=m.title+' · '+(m.release_date||'Unknown date')+' · '+m.source.provider+' ';button.textContent=owned(x)?'Already in library':'Add to library';button.disabled=!!owned(x);row.append(label,button);results.append(row);button.onclick=async()=>{button.disabled=true;try{const detail=await metadataGet('items/'+[m.source.provider,m.kind,m.source.id].map(encodeURIComponent).join('/')+'?enrich=true');const entry=fromMetadata(detail);const existing=owned(entry);if(existing){status.textContent='Already in your library; your edits were preserved.';button.textContent='Already in library';return;}const candidate=items.find(y=>FolioIdentity.possible(y,entry));if(candidate&&!confirm('A similar title is already in your library: '+candidate.title+'. Provider IDs do not establish that these are the same work. Add as a separate entry?')){button.disabled=false;return;}entry.status='Want to experience';entry.rating=0;entry.notes='';entry.favorite=false;items.unshift(entry);if(!persist()){items.shift();button.disabled=false;return;}button.textContent='Already in library';status.textContent='Added to your library. Source attribution is saved with the entry.';render();}catch(error){status.textContent=error.message;button.disabled=false;}};}}catch(error){if(seq===liveSequence)status.textContent=error.message;}};
